for(const input of [ui.file,ui.emptyFile])input.addEventListener('change',()=>input.files[0]&&openPdf(input.files[0]));ui.objects.addEventListener('change',()=>selectObject(Number(ui.objects.value)));ui.apply.addEventListener('click',()=>replaceText(ui.replacement.value));ui.replacement.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();ui.apply.click()}});ui.download.addEventListener('click',openExportModal);ui.exportClose.addEventListener('click',closeExportModal);ui.exportCancel.addEventListener('click',closeExportModal);ui.exportModal.addEventListener('click',event=>{if(event.target===ui.exportModal||event.target.classList.contains('pdfium-export-backdrop'))closeExportModal()});ui.exportFormats.addEventListener('click',event=>{const button=event.target.closest('[data-format]');if(button)setExportFormat(button.dataset.format)});ui.exportContinue.addEventListener('click',continueExportFlow);document.querySelectorAll('[data-export-skin-choice]').forEach(button=>button.addEventListener('click',()=>setExportSkin(button.dataset.exportSkinChoice)));initialiseExportSkin();
ui.exportEmailClose.addEventListener('click',closeExportEmailModal);ui.exportEmailContinue.addEventListener('click',continueFromExportEmail);ui.exportEmail.addEventListener('input',()=>{ui.exportEmailError.hidden=true});ui.exportEmail.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();continueFromExportEmail()}});ui.exportEmailModal.addEventListener('click',event=>{if(event.target===ui.exportEmailModal||event.target.classList.contains('pdfium-export-backdrop'))closeExportEmailModal()});
