ui.prev.addEventListener('click',()=>{if(pageIndex>0){pageIndex--;loadPage()}});ui.next.addEventListener('click',()=>{if(pageIndex+1<pageCount){pageIndex++;loadPage()}});ui.zoomOut.addEventListener('click',()=>{zoom=Math.max(.5,zoom-.1);renderPage()});ui.zoomIn.addEventListener('click',()=>{zoom=Math.min(2.5,zoom+.1);renderPage()});ui.toggleSidebar.addEventListener('click',()=>document.querySelector('.editor-shell').classList.toggle('sidebar-hidden'));
ui.undo.addEventListener('click',async()=>{if(historyIndex<0)return;const entry=history[historyIndex],documentAnnot=entry.type.startsWith('document-annot-'),imageEntry=entry.type.startsWith('image-'),value=['add','draw-add','draw-remove','markup-add','markup-remove','document-annot-add','document-annot-remove','document-annot-update','image-add','crop'].includes(entry.type)?'remove':entry.before;if(await (imageEntry?applyImageHistory(entry,'remove'):documentAnnot?applyDocumentAnnotHistory(entry,value):applyHistory(entry,value))){historyIndex--;updateHistoryButtons();}});ui.redo.addEventListener('click',async()=>{if(historyIndex>=history.length-1)return;const entry=history[historyIndex+1],documentAnnot=entry.type.startsWith('document-annot-'),imageEntry=entry.type.startsWith('image-'),value=['add','draw-add','draw-remove','markup-add','markup-remove','document-annot-add','document-annot-remove','document-annot-update','image-add','crop'].includes(entry.type)?'insert':entry.after;if(await (imageEntry?applyImageHistory(entry,'insert'):documentAnnot?applyDocumentAnnotHistory(entry,value):applyHistory(entry,value))){historyIndex++;updateHistoryButtons();}});

buildImageOverlay=function(scale,pageHeight){for(const [object,spec] of imageSpecs){if(spec.pageIndex!==pageIndex)continue;const hit=document.createElement('div');hit.className=`image-hit${selectedImageObject===object?' selected':''}`;hit.style.left=`${spec.x*scale}px`;hit.style.top=`${(pageHeight-spec.y-spec.height)*scale}px`;hit.style.width=`${spec.width*scale}px`;hit.style.height=`${spec.height*scale}px`;if(spec.previewUrl)hit.style.backgroundImage=`url(${JSON.stringify(spec.previewUrl)})`;for(const corner of ['nw','ne','sw','se']){const handle=document.createElement('span');handle.className=`image-handle ${corner}`;handle.addEventListener('pointerdown',event=>startImageResize(event,object,spec,corner,hit));hit.append(handle)}hit.addEventListener('pointerdown',event=>{if(event.target!==hit)return;if(selectedImageObject!==object){event.preventDefault();event.stopPropagation();selectedImageObject=object;selectedIndex=-1;hit.classList.add('selected');setTool(spec.kind==='watermark'?'watermark':'image');setStatus(spec.kind==='watermark'?'Watermark selected. Its controls are available above.':'Image selected. Drag it, resize from a corner, or press Delete.')}startImageMove(event,object,spec,hit)});hit.addEventListener('click',event=>event.stopPropagation());ui.textOverlay.append(hit)}};
renderPage=function(rebuildOverlay=true){const scale=1.35*zoom,w=Math.max(1,Math.round(M._FPDF_GetPageWidthF(page)*scale)),h=Math.max(1,Math.round(M._FPDF_GetPageHeightF(page)*scale)),pageObjects=[],currentObjects=new Set();for(let i=0,count=M._FPDFPage_CountObjects(page);i<count;i++){const object=M._FPDFPage_GetObject(page,i);pageObjects.push(object);currentObjects.add(object)}const overlayObjects=new Set(imageSpecs.keys());for(const spec of addedSpecs.values())for(const object of spec.objects||[])overlayObjects.add(object);const temporarilyRemoved=pageObjects.filter(object=>overlayObjects.has(object));for(const object of temporarilyRemoved)M._FPDFPage_RemoveObject(page,object);let bitmap=0;try{bitmap=M._FPDFBitmap_Create(w,h,1);M._FPDFBitmap_FillRect(bitmap,0,0,w,h,0xffffffff);M._FPDF_RenderPageBitmap(bitmap,page,0,0,w,h,0,0x01);const ptr=M._FPDFBitmap_GetBuffer(bitmap),stride=M._FPDFBitmap_GetStride(bitmap),out=new Uint8ClampedArray(w*h*4);for(let y=0;y<h;y++)for(let x=0;x<w;x++){const s=ptr+y*stride+x*4,d=(y*w+x)*4;out[d]=M.HEAPU8[s+2];out[d+1]=M.HEAPU8[s+1];out[d+2]=M.HEAPU8[s];out[d+3]=M.HEAPU8[s+3]}ui.canvas.width=w;ui.canvas.height=h;ui.canvas.getContext('2d').putImageData(new ImageData(out,w,h),0,0)}finally{if(bitmap)M._FPDFBitmap_Destroy(bitmap);for(const object of temporarilyRemoved)M._FPDFPage_InsertObject(page,object)}ui.drawOverlay.width=w;ui.drawOverlay.height=h;ui.pageWrap.style.width=`${w}px`;ui.pageWrap.style.height=`${h}px`;const tw=190,th=Math.round(h*(tw/w));ui.thumbnail.width=tw;ui.thumbnail.height=th;ui.thumbnail.getContext('2d').drawImage(ui.canvas,0,0,tw,th);ui.zoomLabel.textContent=`${Math.round(zoom*100)}%`;if(rebuildOverlay)buildTextOverlay()};
async function commitWatermark(){if(!watermarkDirty)return;watermarkDirty=false;await applyWatermark(true)}
for(const control of [ui.watermarkText,ui.watermarkSize,ui.watermarkOpacity,ui.watermarkVertical,ui.watermarkAngle,ui.watermarkColour])control.addEventListener('change',()=>commitWatermark().catch(error=>setStatus(error.message||'The watermark could not be updated.',true)));
ui.shapeFillButton.addEventListener('click',event=>{event.preventDefault();event.stopImmediatePropagation();ui.shapeFillPanel.hidden=true;if(typeof ui.shapeFillColour.showPicker==='function')ui.shapeFillColour.showPicker();else ui.shapeFillColour.click()},{capture:true});
const shapeNoFillLabel=document.createElement('label');shapeNoFillLabel.className='shape-no-fill-toggle';shapeNoFillLabel.innerHTML='<input id="shapeNoFillToggle" type="checkbox" checked><span>No fill</span>';ui.shapeFillButton.after(shapeNoFillLabel);const shapeNoFillToggle=shapeNoFillLabel.querySelector('input'),syncShapeFillBase=syncShapeFill;syncShapeFill=function(colour){syncShapeFillBase(colour);shapeNoFillToggle.checked=!colour};shapeNoFillToggle.addEventListener('change',()=>{if(shapeNoFillToggle.checked)syncShapeFill(null);else if(typeof ui.shapeFillColour.showPicker==='function')ui.shapeFillColour.showPicker();else ui.shapeFillColour.click()});ui.shapeFillColour.addEventListener('input',()=>{shapeNoFillToggle.checked=false},{capture:true});
savePdf=async function(){await commitWatermark();if(downloadSplitPoints.length){const bounds=[0,...downloadSplitPoints.filter(value=>value>0&&value<pageCount),pageCount];for(let i=0;i<bounds.length-1;i++){const split=M._FPDF_CreateNewDocument(),range=cString(`${bounds[i]+1}-${bounds[i+1]}`),ok=M._FPDF_ImportPages(split,doc,range,0);free(range);if(!ok){M._FPDF_CloseDocument(split);throw new Error('PDFium could not create the split PDF')}const blob=await documentBlob(split);M._FPDF_CloseDocument(split);downloadBlob(blob,fileName.replace(/\.pdf$/i,`-part-${i+1}.pdf`))}setStatus(`${bounds.length-1} split PDFs saved.`);return}const blob=await documentBlob(doc);downloadBlob(blob,fileName);setStatus(`Saved ${Math.round(blob.size/1024)} KB.`)};
M=await createPDFiumModule({printErr:message=>console.error('[PDFium]',message)});M._FPDF_InitLibrary();ui.emptyFile.disabled=false;activeTool=requestedEditorTool();setTool(activeTool);try{const transferredPdf=await takeTransferredPdf();if(transferredPdf)await openPdf(transferredPdf);else setStatus('PDFium ready. Select a PDF to begin.')}catch(error){console.error('[PDFBreeze transfer]',error);setStatus('PDFium ready. Select a PDF to begin.')}finally{document.body.classList.remove('transfer-pending')}
